INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Do I need to provide water and electricity?', 'Yes, we request customers to provide basic water and electricity access for best results. Our team brings all other tools and chemicals required.', 1, 1, '2026-07-04 10:36:40', '2026-07-04 10:36:40'),
(2, 'How often should I get my car washed?', 'For best results, we recommend a regular wash weekly or bi-weekly. Deep interior cleaning is ideal every 4 to 6 months.', 2, 1, '2026-07-04 10:36:40', '2026-07-04 10:36:40'),
(3, 'Is the service truly at my doorstep?', 'Yes! All our services are completely doorstep-based, so you don\'t have to go anywhere — we come to your home or office.', 3, 1, '2026-07-04 10:36:40', '2026-07-04 10:36:40'),
(4, 'Are your cleaning products safe for the environment?', 'Absolutely. We use premium, eco-friendly, and biodegradable cleaning agents that are safe for your vehicle and the environment.', 4, 1, '2026-07-04 10:36:40', '2026-07-04 10:36:40'),
(5, 'fdfs', 'sdfs', 0, 1, '2026-07-04 10:40:39', '2026-07-04 10:40:39');
